  esac
  exit 0
fi
case "\$MODE" in
  ok) exit 0 ;;
  drop-closed-header)
    echo '$droppedClosedHeader'
    exit 1 ;;
  drop-conn-reset)
    echo '$droppedConnReset'
    exit 1 ;;

